    private McTable _table;

    public DrawingEmbedder(Document document, McTable table)
    {
        if (document == null) throw new ArgumentNullException(nameof(document), "The document cannot be null.");
        if (table == null) throw new ArgumentNullException(nameof(table), "The table cannot be null.");

        _document = document;
        _table = table;
    }

    public void EmbedPrimitivesIntoTableCell(List<EntityGeometry> entityGeometries, int rowIndex, int columnIndex)
    {
        if (entityGeometries == null) throw new ArgumentNullException(nameof(entityGeometries), "The list of entity geometries cannot be null.");
        if (rowIndex < 0) throw new ArgumentOutOfRangeException(nameof(rowIndex), "Row index must be non-negative.");
        if (columnIndex < 0) throw new ArgumentOutOfRangeException(nameof(columnIndex), "Column index must be non-negative.");

        try
        {
            foreach (var geom in entityGeometries)
            {
                if (geom == null) continue; // Skip null entries in the list

                // Check the type of geometry and extract relevant data
                switch (geom.Type)
                {
                    case GeometryType.Point:
                        // Process point geometry
                        var point = geom.Points.FirstOrDefault();
                        if (point != null)
                        {
                            var newEntity = _document.CreatePointEntity(point);
                            _table.SetCellContent(rowIndex, columnIndex, newEntity);
                        }
                        break;

                    case GeometryType.Line:
                        // Process line geometry
                        if (geom.Points.Count >= 2)
                        {
                            var startPoint = geom.Points[0];
                            var endPoint = geom.Points[1];
                            var newEntity = _document.CreateLineEntity(startPoint, endPoint, geom.Attributes);
                            _table.SetCellContent(rowIndex, columnIndex, newEntity);
                        }
                        break;

                    case GeometryType.Polygon:
                        // Process polygon geometry
                        if (geom.Points.Count > 2)
